  1→{
  2→  "$schema": "https://json.schemastore.org/claude-code-settings.json",
  3→  "hooks": {
  4→    "PreToolUse": [
  5→      {
  6→        "matcher": "tool == \"Bash\" && tool_input.command matches \"(npm run dev|pnpm( run)? dev|yarn dev|bun run dev|uvicorn|flask run|python.*manage\\\\.py runserver|uv run.*(uvicorn|flask|manage\\\\.py))\"",
  7→        "hooks": [
  8→          {
  9→            "type": "command",
 10→            "command": "node -e \"console.error('[Hook] BLOCKED: Dev server must run in tmux for log access');console.error('[Hook] Use: tmux new-session -d -s dev \\\"npm run dev\\\"');console.error('[Hook] Then: tmux attach -t dev');process.exit(1)\""
 11→          }
 12→        ],
 13→        "description": "Block dev servers outside tmux - ensures you can access logs (includes Python servers)"
 14→      },
 15→      {
 16→        "matcher": "tool == \"Bash\" && tool_input.command matches \"(npm (install|test)|pnpm (install|test)|yarn (install|test)?|bun (install|test)|cargo build|make|docker|pytest|vitest|playwright|gradlew|pip install|uv (install|sync|pip|run)|tox)\"",
 17→        "hooks": [
 18→          {
 19→            "type": "command",
 20→            "command": "node -e \"if(!process.env.TMUX){console.error('[Hook] Consider running in tmux for session persistence');console.error('[Hook] tmux new -s dev  |  tmux attach -t dev')}\""
 21→          }
 22→        ],
 23→        "description": "Reminder to use tmux for long-running commands (includes gradlew, pip, uv)"
 24→      },
 25→      {
 26→        "matcher": "tool == \"Bash\" && tool_input.command matches \"git push\"",
 27→        "hooks": [
 28→          {
 29→            "type": "command",
 30→            "command": "node -e \"console.error('[Hook] Review changes before push...');console.error('[Hook] Continuing with push (remove this hook to add interactive review)')\""
 31→          }
 32→        ],
 33→        "description": "Reminder before git push to review changes"
 34→      },
 35→      {
 36→        "matcher": "tool == \"Write\" && tool_input.file_path matches \"\\\\.(md|txt)$\" && !(tool_input.file_path matches \"README\\\\.md|CLAUDE\\\\.md|AGENTS\\\\.md|CONTRIBUTING\\\\.md\")",
 37→        "hooks": [
 38→          {
 39→            "type": "command",
 40→            "command": "node -e \"const fs=require('fs');let d='';process.stdin.on('data',c=>d+=c);process.stdin.on('end',()=>{const i=JSON.parse(d);const p=i.tool_input?.file_path||'';if(/\\.(md|txt)$/.test(p)&&!/(README|CLAUDE|AGENTS|CONTRIBUTING)\\.md$/.test(p)){console.error('[Hook] BLOCKED: Unnecessary documentation file creation');console.error('[Hook] File: '+p);console.error('[Hook] Use README.md for documentation instead');process.exit(1)}console.log(d)})\""
 41→          }
 42→        ],
 43→        "description": "Block creation of random .md files - keeps docs consolidated"
 44→      }
 45→    ],
 46→    "PostToolUse": [
 47→      {
 48→        "matcher": "tool == \"Bash\"",
 49→        "hooks": [
 50→          {
 51→            "type": "command",
 52→            "command": "node -e \"let d='';process.stdin.on('data',c=>d+=c);process.stdin.on('end',()=>{const i=JSON.parse(d);const cmd=i.tool_input?.command||'';const out=i.tool_output?.output||'';if(/gh pr create/.test(cmd)){const m=out.match(/https:\\/\\/github.com\\/[^/]+\\/[^/]+\\/pull\\/\\d+/);if(m){console.error('[Hook] PR created: '+m[0]);const repo=m[0].replace(/https:\\/\\/github.com\\/([^/]+\\/[^/]+)\\/pull\\/\\d+/,'$1');const pr=m[0].replace(/.*\\/pull\\/(\\d+)/,'$1');console.error('[Hook] To review: gh pr review '+pr+' --repo '+repo)}}if(/glab mr create/.test(cmd)){const m=out.match(/https?:\\/\\/labs\\.cowave\\.kr\\/[^\\s]+\\/-\\/merge_requests\\/\\d+/);if(m){console.error('[Hook] MR created: '+m[0]);const mr=m[0].replace(/.*\\/merge_requests\\/(\\d+)/,'$1');console.error('[Hook] To view: glab mr view '+mr);console.error('[Hook] To approve: glab mr approve '+mr)}}console.log(d)})\""
 53→          }
 54→        ],
 55→        "description": "Log PR/MR URL and provide review command after GitHub PR or GitLab MR creation"
 56→      },
 57→      {
 58→        "matcher": "tool == \"Bash\" && tool_input.command matches \"(npm run build|pnpm build|yarn build)\"",
 59→        "hooks": [
 60→          {
 61→            "type": "command",
 62→            "command": "node -e \"let d='';process.stdin.on('data',c=>d+=c);process.stdin.on('end',()=>{console.error('[Hook] Build completed - async analysis running in background');console.log(d)})\"",
 63→            "async": true,
 64→            "timeout": 30
 65→          }
 66→        ],
 67→        "description": "Example: async hook for build analysis (runs in background without blocking)"
 68→      },
 69→      {
 70→        "matcher": "tool == \"Bash\" && tool_input.command matches \"gradlew.*build\"",
 71→        "hooks": [
 72→          {
 73→            "type": "command",
 74→            "command": "node -e \"let d='';process.stdin.on('data',c=>d+=c);process.stdin.on('end',()=>{console.error('[Hook] Gradle build completed - async analysis running in background');console.log(d)})\"",
 75→            "async": true,
 76→            "timeout": 60
 77→          }
 78→        ],
 79→        "description": "Async hook for Gradle build analysis (runs in background without blocking)"
 80→      },
 81→      {
 82→        "matcher": "tool == \"Edit\" && tool_input.file_path matches \"\\\\.(ts|tsx|js|jsx)$\"",
 83→        "hooks": [
 84→          {
 85→            "type": "command",
 86→            "command": "node -e \"const{execFileSync}=require('child_process');const fs=require('fs');let d='';process.stdin.on('data',c=>d+=c);process.stdin.on('end',()=>{const i=JSON.parse(d);const p=i.tool_input?.file_path;if(p&&fs.existsSync(p)){try{execFileSync('npx',['prettier','--write',p],{stdio:['pipe','pipe','pipe']})}catch(e){}}console.log(d)})\""
 87→          }
 88→        ],
 89→        "description": "Auto-format JS/TS files with Prettier after edits"
 90→      },
 91→      {
 92→        "matcher": "tool == \"Edit\" && tool_input.file_path matches \"\\\\.(kt|kts)$\"",
 93→        "hooks": [
 94→          {
 95→            "type": "command",
 96→            "command": "node -e \"const{execSync}=require('child_process');const fs=require('fs');const path=require('path');let d='';process.stdin.on('data',c=>d+=c);process.stdin.on('end',()=>{const i=JSON.parse(d);const p=i.tool_input?.file_path;if(p&&fs.existsSync(p)){let dir=path.dirname(p);while(dir!==path.dirname(dir)&&!fs.existsSync(path.join(dir,'build.gradle.kts'))&&!fs.existsSync(path.join(dir,'build.gradle'))&&!fs.existsSync(path.join(dir,'settings.gradle.kts'))&&!fs.existsSync(path.join(dir,'settings.gradle'))){dir=path.dirname(dir)}const hasGradle=fs.existsSync(path.join(dir,'gradlew'));if(hasGradle){try{execSync('./gradlew ktlintFormat 2>&1',{cwd:dir,encoding:'utf8',stdio:['pipe','pipe','pipe'],timeout:60000});console.error('[Hook] ktlintFormat applied to Kotlin files')}catch(e){const out=(e.stdout||'')+(e.stderr||'');const lines=out.split('\\n').filter(l=>l.includes(p)||l.includes('FAILED')).slice(0,10);if(lines.length)console.error('[Hook] ktlintFormat issues:\\n'+lines.join('\\n'))}}}console.log(d)})\""
 97→          }
 98→        ],
 99→        "description": "Auto-format Kotlin files with ktlintFormat after edits"
100→      },

